-- Fuller descriptions and feature lists for the 37 live listings not covered by listing_copy_2026-11-15.sql.
-- Replaces the one-line description, About text and feature list. Images, links, sports, categories and status are untouched.
-- To apply: Supabase dashboard > SQL Editor > paste this whole file > Run. Then press Save on any listing in admin.

update listings set tagline = 'Player prop research for the NBA, NFL, MLB and WNBA, with hit rates and matchup grades.', bio = 'A US player prop research tool on the web, iOS and Android. A sortable board lists each prop line with the player''s recent hit rate, averages, head-to-head record and a matchup grade based on the opponent''s defence and pace. Some rows are locked to paid members. Built for the US sportsbook market.', features = array['Sortable prop board with over and under prices', 'Hit rates over the last 5, 10 and 15 games and the season', 'Matchup grades using opponent defensive rating and pace', 'Saved filter presets', 'iOS and Android apps']::text[] where slug = 'propsmadness';
update listings set tagline = 'AFL, NRL, NBA, NFL, EPL and MLB player stats you can slice your own way.', bio = 'An Australian player stats app for punters. Filter a player''s record by opponent, or see how their numbers change when a team-mate is out injured.', features = array['Player data across Australian and US sport, plus the EPL', 'Performance against specific opponents', 'With and without team-mate splits']::text[] where slug = 'statmate';
update listings set tagline = 'Free advanced analytics for the NFL, fantasy and college football.', bio = 'A football analytics site with the kind of tools usually found behind a paywall: player profiles with opponent-adjusted EPA and success rate, a play-by-play explorer, and game pages with win-probability charts. It also has dynasty rankings and a mock draft simulator. Free with an account.', features = array['Player Lookup with splits and advanced metrics', 'Stats Explorer with custom splits across the league', 'Play Explorer with situation, coverage and result for any snap', 'Game Explorer with win-probability charts', 'Dynasty rankings and a mock draft simulator']::text[] where slug = 'outside-zone';
update listings set tagline = 'Free daily picks and predictions on YouTube across US sports and UFC.', bio = 'A YouTube channel posting free picks, predictions and player props for the NFL, NBA, MLB, WNBA, college football, college basketball and UFC.', features = array['Free picks and prediction videos', 'Player prop picks', 'Covers US pro and college sport, plus UFC']::text[] where slug = 'guy-boston-sports';
update listings set tagline = 'Data and model-driven picks, with a lean toward unders.', bio = 'A US bettor who posts picks built on data analysis and models, mostly unders, staked at 0.5 to 1 unit. Picks are delivered through DubClub.', features = array['Model-based picks', 'Mostly unders', 'Flat staking of 0.5 to 1 unit']::text[] where slug = 'chefsbestbets';
update listings set tagline = 'Stat boards and a bet tracker for the NFL, NBA, NBL and EPL.', bio = 'An Australian stats site with a board for each league it covers (the NFL, EPL, NBA and NBL) and a built-in bet tracker.', features = array['Stat boards by league', 'Built-in bet tracker', 'Covers the NFL, NBA, NBL and EPL']::text[] where slug = 'sportsball-stats';
update listings set tagline = 'A daily sports betting show on YouTube.', bio = 'A US sports betting show that posts new videos every day, covering the NFL, MLB and college football.', features = array['New videos every day', 'NFL, MLB and college football']::text[] where slug = 'hold-the-phone';
update listings set tagline = 'Ask a sports question in plain English and get the stat back.', bio = 'StatMuse answers natural-language questions about players, teams and games, such as a player''s record against one opponent. It covers the NBA, NFL, MLB, NHL, the major European soccer leagues, college football and golf, shows scores and odds, and has iOS and Android apps.', features = array['Natural-language stat search', 'Scores and odds', 'Covers US leagues, European soccer, college football and golf', 'iOS and Android apps']::text[] where slug = 'statmuse';
update listings set tagline = 'NFL, fantasy and draft coverage built on beat writer reporting.', bio = 'Original NFL, fantasy football and draft content from an NFL-credentialed team, combined with curated intel from the beat writers who cover each of the 32 teams. It runs a podcast, a YouTube channel and tools on its site.', features = array['Curated beat writer news for all 32 teams', 'Podcast and YouTube shows', 'Draft and prospect coverage', 'Fantasy football analysis and tools']::text[] where slug = '32beatwriters';
update listings set tagline = 'Betting news, odds, a bet tracker and analysis from a major US betting media brand.', bio = 'Action Network is a US sports betting media company. Its app tracks your bets and shows live odds and public betting data, and its site, podcast and YouTube channel carry analysis and picks from its staff. Much of it is free, with a paid tier for extra tools. It promotes US sportsbooks.', features = array['Bet tracking app', 'Live odds and public betting data', 'Podcast and YouTube channel', 'Staff picks and projections']::text[] where slug = 'action-network';
update listings set tagline = 'Australian and American sport, with weekly one-on-one interviews on Tommy Talks.', bio = 'A digital sports club for fans of Australian and US sport, covering the AFL, NRL, NFL, NBA and more. Its weekly podcast, Tommy Talks, features one-on-one conversations with sporting names.', features = array['Weekly Tommy Talks interview podcast', 'Covers the AFL, NRL, NFL and NBA', 'On Spotify and YouTube']::text[] where slug = 'ausmerican-aces';
update listings set tagline = 'Two US cappers sharing one paid picks community.', bio = 'Austin Props and Dr. Profit run a joint picks community on Winible covering the NBA, NFL and MLB, with both cappers'' picks under one subscription.', features = array['Picks from two cappers', 'One subscription for both', 'Members'' community']::text[] where slug = 'austin-props-and-dr-profit';
update listings set tagline = 'Consensus picks, prop tools and odds from the FantasyPros team.', bio = 'BettingPros gathers picks from a large panel of experts into a consensus, alongside odds comparison, prop bet tools and bet tracking in its app. It is the betting arm of FantasyPros and is built for the US sportsbook market.', features = array['Consensus expert picks', 'Player prop tools', 'Odds comparison', 'Bet tracking app', 'YouTube channel']::text[] where slug = 'bettingpros';
update listings set tagline = 'Free bet tracking built for Australian punters and matched bettors.', bio = 'A bet tracking platform for Australian punters. A browser extension records your bets from bookmaker sites, so results and profit and loss are kept without manual entry.', features = array['Bet tracking with profit and loss', 'Browser extension that records bets from bookmaker sites', 'Built for matched betting as well as punting', 'Free to use']::text[] where slug = 'bettrackr';
update listings set tagline = 'A sports betting entertainment brand with shows, a community and an app.', bio = 'Bookit Sports describes itself as the home of sports betting entertainment. It makes video shows for YouTube and runs an app built around community and competition between bettors.', features = array['YouTube shows', 'Community app', 'Covers US sport and the NBL']::text[] where slug = 'bookit-sports';
update listings set tagline = 'Australian racing and sports analysts offering paid memberships.', bio = 'A long-running Australian service that hosts professional racing and sports analysts, each sold as a separate membership package. Packages include horse racing and rugby league.', features = array['Membership packages by analyst', 'Horse racing and sports coverage', 'Based in Australia']::text[] where slug = 'champion-bets';
update listings set tagline = 'Daily NBA player prop breakdowns that teach the process, not just the pick.', bio = 'An NBA player props education channel on YouTube. Each video walks through the data behind the day''s bets: minutes projections, usage rates and defensive matchups, with closing line value tracked over time. New videos daily during the NBA season.', features = array['Daily videos during the NBA season', 'Minutes, usage and matchup analysis', 'Closing line value tracking']::text[] where slug = 'daft-previews';
update listings set tagline = 'Data-driven fantasy football analysis for DFS, best ball and redraft.', bio = 'A fantasy football analyst who uses data to cover daily fantasy, best ball, redraft and other formats, with content on X and their own site.', features = array['Covers DFS, best ball and redraft', 'Data-led analysis', 'NFL only']::text[] where slug = 'dataroma';
update listings set tagline = 'AFL statistics, fixtures, team selections and fantasy scores.', bio = 'A long-running AFL statistics site. It has player and team stats, fixtures and results, weekly team selections and fantasy scoring data, all free.', features = array['Player and team statistics', 'Fixtures and results', 'Weekly team selections', 'Fantasy scores']::text[] where slug = 'footywire';
update listings set tagline = 'Sports betting and fantasy picks from a former college athlete.', bio = 'A US bettor posting NBA and NFL betting and fantasy content, with picks delivered through DubClub. Says he played Division I college baseball and now bets full time (self-described).', features = array['NBA and NFL picks', 'Fantasy sports content', 'Picks delivered through DubClub']::text[] where slug = 'goatedgambler77';
update listings set tagline = 'Daily NBA, NFL and MLB picks with projections and research.', bio = 'A US picks and education service with daily NBA, NFL and MLB picks, projections and research, on YouTube and its own site.', features = array['Daily picks', 'Projections and research', 'YouTube channel']::text[] where slug = 'land-your-bets';
update listings set tagline = 'Analytical fantasy football podcasts and draft guides from JJ Zachariason.', bio = 'Late-Round Fantasy Football produces year-round fantasy football content across several shows and streams, plus draft guides, all built on the same analytical approach.', features = array['The Late-Round Podcast and other shows', 'Draft guides', 'Year-round coverage, including the offseason']::text[] where slug = 'late-round-fantasy-football';
update listings set tagline = 'Player prop research built on trends and hit rates.', bio = 'Linemate is a prop research tool that surfaces betting trends: how often a player has cleared a line recently, against an opponent or in a given situation. Available on the web and as an app.', features = array['Trend-based prop discovery', 'Hit rates by recent form and matchup', 'Web and mobile apps']::text[] where slug = 'linemate';
update listings set tagline = 'NFL and fantasy football breakdowns with an entertainment lean.', bio = 'A YouTube channel covering the NFL and fantasy football with breakdowns made to be watched as much as studied.', features = array['NFL breakdowns', 'Fantasy football content', 'YouTube and Instagram']::text[] where slug = 'loeb-s-leads';
update listings set tagline = 'Wide receiver evaluation built on hand-charted route data since 2014.', bio = 'Matt Harmon''s Reception Perception charts wide receivers route by route to measure how often they get open, against different coverages and on each route type. It''s used for fantasy football and for evaluating NFL players and draft prospects.', features = array['Route-by-route charting for each receiver', 'Success rates against man, zone and press coverage', 'NFL player and draft prospect profiles', 'YouTube channel']::text[] where slug = 'reception-perception';
update listings set tagline = 'Fantasy sports news and analysis from a large writing team, mostly free.', bio = 'RotoBaller publishes player news, rankings and fantasy analysis across the NFL, NBA, MLB, NHL and college football. It says its team of more than 150 writers and editors produces original, human-written content, most of it free.', features = array['Real-time player news', 'Rankings and fantasy analysis', 'Covers the NFL, NBA, MLB, NHL and college football', 'Mostly free']::text[] where slug = 'rotoballer';
update listings set tagline = 'The reference databases for US sport, from Baseball Reference to Pro Football Reference.', bio = 'Sports Reference runs Baseball Reference, Basketball Reference, Pro Football Reference and Hockey Reference: free databases of player, team and game statistics going back through each league''s history. Its paid Stathead tool lets you run custom searches, and its YouTube channel has tutorials.', features = array['Historical stats for every player, team and season', 'Box scores and game logs', 'Stathead custom search (paid)', 'Tutorial videos on YouTube']::text[] where slug = 'sports-reference';
update listings set tagline = 'Daily best bets from SportsLine''s handicappers on The Early Edge.', bio = 'SportsLine is the picks and projections service owned by CBS Sports. Its show The Early Edge runs every weekday at 10am US Eastern, with its handicappers giving picks against the spread and prop plays for the day''s games.', features = array['The Early Edge every weekday', 'Picks against the spread and props', 'Covers the major US sports']::text[] where slug = 'sportsline';
update listings set tagline = 'AFL predictions and ladder forecasts from dozens of public models, in one place.', bio = 'Squiggle gathers AFL prediction models from around the web, shows each one''s tips for the round and tracks how accurate they have been. It also has a ladder predictor. Free.', features = array['Tips from dozens of public models', 'Leaderboard of model accuracy', 'Ladder predictor', 'Free']::text[] where slug = 'squiggle';
update listings set tagline = 'Teaching you how to research bets on your own, and what information actually matters.', bio = 'A YouTube channel that teaches bettors to do their own research and work out which information matters, focused on the NBA and NFL.', features = array['Betting research tutorials', 'NBA and NFL focus', 'YouTube channel']::text[] where slug = 'straight-bettin';
update listings set tagline = 'NBA and NBL player prop picks.', bio = 'An NBA prop bettor who also covers the NZNBL and NBL1, with picks run through Discord. States seven years'' experience and a tracked record of 400 units profit (self-reported; not checked by Grinners).', features = array['NBA player prop picks', 'NZNBL and NBL1 coverage', 'Discord community']::text[] where slug = 'swish-bets';
update listings set tagline = 'NFL-led betting analysis, previews and best bets.', bio = 'A US sports betting podcast with game previews, analysis and best bets. It covers several sports and is strongest during the NFL season.', features = array['Game previews and best bets', 'Strongest in NFL season', 'On Spotify']::text[] where slug = 'the-favorites';
update listings set tagline = 'Sports betting education and discussion from professional bettors.', bio = 'A YouTube channel and media network that is home to the Circles Off podcast and a sports betting education series, hosted by people who bet for a living.', features = array['Home of Circles Off', 'Betting education series', 'YouTube channel']::text[] where slug = 'the-hammer-betting-network';
update listings set tagline = 'NBA, MLB, NFL and WNBA picks and breakdowns.', bio = 'A US capper who studies and breaks down NBA, MLB, NFL and WNBA games, with picks delivered through DubClub.', features = array['NBA, MLB, NFL and WNBA picks', 'Game breakdowns', 'Picks delivered through DubClub']::text[] where slug = 'thechefkayy';
update listings set tagline = 'Line shopping, a market-derived fair line and prop tools for serious bettors.', bio = 'Unabated is a betting toolset built around line shopping and closing line value. Its odds screen compares sportsbooks against the Unabated Line, a fair price calculated from the market, and it adds player prop tools, calculators and educational content. Built for the US sportsbook market.', features = array['Odds screen for line shopping', 'The Unabated Line, a calculated fair price', 'Player prop tools', 'Betting calculators', 'Podcast and YouTube education']::text[] where slug = 'unabated';
update listings set tagline = 'An NBL podcast with a focus on NBL SuperCoach.', bio = 'An Australian basketball podcast started in 2023. It began with team-by-team NBL chat and now leans toward fantasy, with advice for NBL SuperCoach through the season.', features = array['NBL SuperCoach advice', 'NBL team and player discussion', 'On Spotify']::text[] where slug = 'usage-rate-podcast';
update listings set tagline = 'An Australian social betting app for following pro punters and tipping with mates.', bio = 'Wolfden is an Australian punting community and app, founded by a group of mates. Members follow tips from professional punters, tip alongside friends and get betting education, with more content on YouTube. Says more than 60,000 Australians have joined (self-reported).', features = array['Follow and copy pro punters'' tips', 'Tip with mates', 'Betting education', 'YouTube channel']::text[] where slug = 'wolfden';
